local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[40011902]=b({e[11057],40011902,1,4,492,"「ん～～……\n人が多い所だと撮られちゃうし～、穴場スポットも全部行っちゃったし～、次のデート、どこですればいいかなぁ？\nせっかくのオフの日だもん、スウィーティーとゆっくり羽を伸ばしたいんだよね。\nねぇねぇ、一緒に考えてよぉ。絶対に邪魔されない場所がいいの、おねがぁい♡」",20000119,1,"deco/character/miya_0",302002,60,"miya_0",false,0},h)g[40011903]=b({e[17045],40011903,3,61,493,"「お菓子のおねだりなんて、コドモのすることでしょぉ～？\nミアのお目当ては、初めからず～っと、スウィーティーだけだよぉ。\nだってぇ、お菓子なんかよりも、スウィーティーの方が好みだも～ん。\nね、ちょっと近くに来てよ。味見、さ・せ・て♡」",20000119,2,false,false,false,false,false,false,false,false,"0",1,4864,5000,2380,3095,5333,8333,6500,10333,8000,8000,5333,false,false,0},h)g[40012001]=b({e[11057],40012001,false,207,494,false,20000120,false,"deco/character/jinwu",302002,60,"jinwu"},h)g[40012002]=b({e[11057],40012002,1,4,495,"「梅雨は……嫌いでち。\n羽根がいつまで経っても乾きまちぇん……。\nキンウのこと、助けてくだちゃい……！」",20000120,1,"deco/character/jinwu_0",302002,60,"jinwu_0"},h)g[40012101]=b({e[11057],40012101,false,208,496,false,20000121,false,"deco/character/40012101",302002,60,"chilin",false,0},h)g[40012102]=b({e[11045],40012102,1,4,497,"「く～！ たまには、一杯やるのも乙なもんだな。\nいつもはとにかく前に前に！ って走ってるけど、今日くらいは……\nや、君のそばにいる時は、少しペースを落としてみてもいいかなと思ってさ。\nほら、もう少しこっちに寄ってくれ。\n貴重な休息の時、一緒に満喫しよう！」",20000121,1,"deco/character/40012102",302002,60,2,4075,5000,2154,3715,false,4900,6833,5600,8000,5166,false,"chilin_0",false,0},h)g[40012103]=b({e[9045],40012103,999,209,498,"「ふははははっ！ どうだ、我のこの姿を見るのは初めてであろう！\n案ずるな、この燃え盛る赤き炎は我が意のまま。汝を傷つけるような真似は決してせぬ！\nなんといっても、蔓延る怠惰と厄運をもろとも焼き尽くし、民の安寧を護り抜くのが我が役目ゆえな。\nたまにはこうして、本気を出してやらねばならぬのだ！」",20000121,2,"deco/character/40012103",2,5908,5000,3050,4993,2666,8000,8000,8000,8000,8000,8000,"chilin_1",false,0},h)g[40012201]=b({e[14057],40012201,false,210,499,false,20000122,false,"deco/character/tongren",302002,60,false,false,1,"tongren"},h)g[40012202]=b({e[14057],40012202,1,4,500,false,20000122,1,"deco/character/tongren_0",302002,60,false,false,1,"tongren_0"},h)g[40012203]=b({e[14045],40012203,999,211,501,"「よし、次は全力であの大波を越えるぞ！」",20000122,3,"deco/character/tongren_1",false,false,false,false,1,1,6035,5000,2830,4654,10000,6800,9833,6266,9000,8000,1666,"tongren_1"},h)g[40012301]=b({e[14057],40012301,false,212,502,false,20000123,false,"deco/character/yasina",302002,60,false,false,1,"yasina"},h)g[40012302]=b({e[14057],40012302,1,4,503,false,20000123,1,"deco/character/yasina_0",302002,60,false,false,1,"yasina_0"},h)g[40012303]=b({e[14045],40012303,999,211,504,"「ん～……たまにはこうやって、のんびり過ごすのも良いよね。」",20000123,3,"deco/character/yasina_1",false,false,false,false,1,1,5263,5000,2743,2672,12000,8000,8000,8000,12000,8000,8000,"yasina_1"},h)g[40012401]=b({e[14057],40012401,false,213,505,false,20000124,false,"deco/character/lifa",302002,60,false,false,1,"lifa"},h)g[40012402]=b({e[14057],40012402,1,4,506,false,20000124,1,"deco/character/lifa_0",302002,60,false,false,1,"lifa_0"},h)g[40012403]=b({e[14045],40012403,999,211,507,"「楽しかったなー！ 日が沈むまでちょっと一休みして、潮風に当たらない？」",20000124,3,"deco/character/lifa_1",false,false,false,false,1,1,4348,5000,2140,3481,6000,5333,9666,5666,13000,8000,2666,"lifa_1"},h)g[40012501]=b({e[14057],40012501,false,214,508,false,20000125,false,"deco/character/shinai",302002,60,false,false,1,"shinai"},h)g[40012502]=b({e[14057],40012502,1,4,509,false,20000125,1,"deco/character/shinai_0",302002,60,false,false,1,"shinai_0"},h)g[40012503]=b({e[14045],40012503,999,211,510,"「今日はこのまま、ここで静かに過ごすのも悪くないわね。」",20000125,3,"deco/character/shinai_1",false,false,false,false,1,1,4695,5000,2402,3060,4000,5733,8000,8000,11967,8000,8000,"shinai_1"},h)g[40012601]=b({e[11059],40012601,false,215,511,false,20000126,false,"deco/character/40012601",302002,60,0},h)g[40012602]=b({e[11059],40012602,1,4,512,"「うわマジか、君のそばにいるだけで、エモいアイデアが次々湧いてくんだけど！\nうひょ～、ペンが勝手に走り出してもう止まらん……！\nあ、せっかくのボーナスタイム中だし、記念になんか描く？\nえーと、モフィーの……アシスタント、ファン、取材対象、第一読者さんへ……\nうは～、書くスペース足んね～！」",20000126,1,"deco/character/40012602",302002,60,0},h)g[40012701]=b({e[11059],40012701,false,216,513,false,20000127,false,false,302002,60,0},h)g[40012702]=b({e[11059],40012702,1,4,514,"「ふう……今回の演奏は、思っていたよりも気を張っていたようです。客席に、特別な人がいたからでしょうか。\nそれで……いかがでしたか？ その、いつもと比べて、何か……いえ、演奏以外の感想をお聞きしたくて。\nあなたの感想を聞けるのは、私にとって、どんな賞をいただくよりも大切なことです。」",20000127,1,false,302002,60,0},h)g[40012801]=b({e[14059],40012801,false,217,515,false,20000128,false,"deco/character/40012801",302002,60,false,false,1,0},h)g[40012802]=b({e[14059],40012802,1,4,516,false,20000128,1,"deco/character/40012802",302002,60,false,false,1,0},h)g[40012803]=b({e[14045],40012803,999,218,517,"「夜空をたくさんの光が駆け抜けていく夢を見た気がするよ。」",20000128,3,"deco/character/40012803",false,false,false,false,1,1,6035,5000,2830,4654,10000,6800,9833,6266,9000,8000,1666,false,false,0},h)g[40012901]=b({e[14059],40012901,false,219,518,false,20000129,false,"deco/character/40012901",302002,60,false,false,1,0},h)g[40012902]=b({e[14059],40012902,1,4,519,false,20000129,1,"deco/character/40012902",302002,60,false,false,1,0},h)g[40012903]=b({e[14045],40012903,999,218,520,"「静かな夜ですね。こういう時には、この魔法を使いたくなります。……なんだか心が落ち着くんです。」",20000129,3,"deco/character/40012903",false,false,false,false,1,1,5263,5000,2743,2672,12000,8000,8000,8000,12000,8000,8000,false,false,0},h)g[40013001]=b({e[14059],40013001,false,220,521,false,20000130,false,"deco/character/40013001",302002,60,false,false,1,0},h)g[40013002]=b({e[14059],40013002,1,4,522,false,20000130,1,"deco/character/40013002",302002,60,false,false,1,0},h)g[40013003]=b({e[14045],40013003,999,218,523,"「お手伝いも終わったし、午後はのんびりするか。ふぅ……平和だなぁ〜。」",20000130,3,"deco/character/40013003",false,false,false,false,1,1,4348,5000,2140,3481,6000,5333,9666,5666,13000,8000,2666,false,false,0},h)g[40013101]=b({e[14059],40013101,false,221,524,false,20000131,false,"deco/character/40013101",302002,60,false,false,1,0},h)g[40013102]=b({e[14059],40013102,1,4,525,false,20000131,1,"deco/character/40013102",302002,60,false,false,1,0},h)g[40013103]=b({e[14045],40013103,999,218,526,"「綺麗な氷面だったけど……砕けたあとのほうが、私は好きかも。」",20000131,3,"deco/character/40013103",false,false,false,false,1,1,4695,5000,24